// Razem reminders — Cloudflare Worker. GENERATED by server/build-worker.mjs from recur.js, core.mjs, runner.mjs, worker-entry.mjs.
// Secrets: FIREBASE_SERVICE_ACCOUNT, VAPID_PUBLIC, VAPID_PRIVATE, VAPID_SUBJECT, RUN_TOKEN. Trigger: cron "*/2 * * * *".

// ===== ../recur.js =====
// Shared date / recurrence logic — used by the app AND the reminder server.
const DAY = 86400000;
const pad = n => String(n).padStart(2, '0');
const ymd = d => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
function parseYmd(s) { const [y, m, d] = s.split('-').map(Number); return new Date(y, m - 1, d); }
function addDays(s, n) { const d = parseYmd(s); d.setDate(d.getDate() + n); return ymd(d); }
const toMin = s => { const [h, m] = s.split(':').map(Number); return h * 60 + m; };
const dayDiff = (a, b) => Math.round((parseYmd(b) - parseYmd(a)) / DAY);
function weekStart(d) { const x = new Date(d); x.setDate(x.getDate() - ((x.getDay() + 6) % 7)); return x; }

const isRecurring = t => !!(t.repeat && t.repeat.type && t.repeat.type !== 'none');
const compId = (taskId, date) => `${taskId}_${date}`;

/** Does task occur on date (YYYY-MM-DD)? */
function occursOn(task, date) {
  if (!task || !task.date || date < task.date) return false;
  if (task.until && date > task.until) return false;
  const r = task.repeat || { type: 'none' };
  const every = Math.max(1, parseInt(r.every) || 1);
  const s = parseYmd(task.date), d = parseYmd(date);
  switch (r.type) {
    case 'daily': return dayDiff(task.date, date) % every === 0;
    case 'weekly': {
      const days = r.days && r.days.length ? r.days : [s.getDay()];
      if (!days.includes(d.getDay())) return false;
      return Math.round((weekStart(d) - weekStart(s)) / (7 * DAY)) % every === 0;
    }
    case 'monthly': {
      const months = (d.getFullYear() - s.getFullYear()) * 12 + d.getMonth() - s.getMonth();
      if (months % every !== 0) return false;
      const last = new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate();
      return d.getDate() === Math.min(s.getDate(), last);
    }
    default: return date === task.date;
  }
}

const assignedTo = (t, uid) => !uid || !t.assignee || t.assignee === 'all' || t.assignee === uid;

/** % completion for a day. Skipped occurrences are left out of the total. */
function dayStats(tasks, comps, date, uid) {
  let total = 0, done = 0;
  for (const t of tasks) {
    if (!occursOn(t, date) || !assignedTo(t, uid)) continue;
    const c = comps[compId(t.id, date)];
    if (c && c.status === 'skip') continue;
    total++;
    if (c && c.status === 'done') done++;
  }
  return { total, done, pct: total ? Math.round(done * 100 / total) : null };
}

/** One-off tasks from before `date` that were never completed. */
function overdue(tasks, comps, date, uid) {
  return tasks.filter(t => !isRecurring(t) && t.date < date && assignedTo(t, uid) && !comps[compId(t.id, t.date)]);
}

/** Current date + minutes-since-midnight in a time zone. */
function nowInTz(tz, now = new Date()) {
  const p = Object.fromEntries(new Intl.DateTimeFormat('en-CA', {
    timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23'
  }).formatToParts(now).map(x => [x.type, x.value]));
  return { date: `${p.year}-${p.month}-${p.day}`, minutes: parseInt(p.hour) * 60 + parseInt(p.minute) };
}

/** Reminder offsets (minutes before the task time). Recurring: 5 min before. One-off: day before + 2 h before. */
const defaultRemind = recurring => recurring ? { on: true, offsets: [5], nag: 30 } : { on: true, offsets: [1440, 120], nag: 60 };
function remindOffsets(task) {
  const r = task.remind; if (!r || r.on === false || !task.time) return [];
  if (Array.isArray(r.offsets)) return r.offsets;
  return [r.before || 0]; // older format
}

/** Recurring occurrences on `date` that nobody marked (done / not done / skipped). */
function unfinished(tasks, comps, date, uid) {
  return tasks.filter(t => isRecurring(t) && occursOn(t, date) && assignedTo(t, uid) && !comps[compId(t.id, date)]);
}

/** First/last date of a month "YYYY-MM". */
function monthRange(ym) {
  const [y, m] = ym.split('-').map(Number), days = new Date(y, m, 0).getDate();
  return { first: `${ym}-01`, last: `${ym}-${pad(days)}`, days };
}
const prevMonth = ym => { const [y, m] = ym.split('-').map(Number); return ymd(new Date(y, m - 2, 1)).slice(0, 7); };

/**
 * Month summary: per task and in total, how many times it was due, done, marked not done, skipped or left open.
 * upTo = last date to count (today, for the running month). % = done / (due - skipped).
 */
function monthStats(tasks, comps, ym, { uid = null, upTo = null } = {}) {
  const { first, last } = monthRange(ym), end = upTo && upTo < last ? upTo : last;
  const K = ['occ', 'done', 'missed', 'skip', 'open'], total = { occ: 0, done: 0, missed: 0, skip: 0, open: 0 }, rows = [];
  for (const t of tasks) {
    if (!assignedTo(t, uid) || (t.date && t.date > end) || (t.until && t.until < first)) continue;
    const r = { task: t, occ: 0, done: 0, missed: 0, skip: 0, open: 0 };
    for (let d = first; d <= end; d = addDays(d, 1)) {
      if (!occursOn(t, d)) continue;
      r.occ++;
      const s = comps[compId(t.id, d)]?.status;
      if (s === 'done') r.done++; else if (s === 'missed') r.missed++; else if (s === 'skip') r.skip++; else r.open++;
    }
    if (r.occ) { rows.push(r); K.forEach(k => { total[k] += r[k]; }); }
  }
  const pct = x => (x.occ - x.skip) > 0 ? Math.round(x.done * 100 / (x.occ - x.skip)) : null;
  rows.forEach(r => { r.pct = pct(r); });
  total.pct = pct(total);
  return { rows, total, end };
}

// ===== core.mjs =====
// Reminder rules — pure functions, no database code.
// Any backend (the Firestore runner in remind.mjs today, a Pi/PocketBase server later) feeds data in and gets messages out.

const WINDOW = 90;     // still send a reminder up to 90 min after its moment (worker may run late)
const LOOKAHEAD = 3;   // days ahead to check (offsets go up to 2 days)
const LATE = 30;       // GitHub's scheduler can be late: still send a missed 'before' reminder up to 30 min after the time

const fmtOff = m => m >= 60 ? `${m / 60} h` : `${m} min`;
const MSG = {
  pl: {
    pre: (off, tm, k) => k === 0 ? (off ? `Za ${fmtOff(off)} · ${tm}` : `Teraz · ${tm}`) : k === 1 ? `Jutro o ${tm}` : `Za ${k} dni, o ${tm}`,
    fu: tm => `Było na ${tm} — zrobione?`, done: '✓ Zrobione', missed: '✕ Nie zrobione',
    mTitle: 'Dzień dobry ☀️', mBody: (n, list) => `Dziś ${n} ${n === 1 ? 'zadanie' : n < 5 ? 'zadania' : 'zadań'}: ${list}`,
    yday: n => `Wczoraj niezamknięte: ${n}`, dinner: n => `Obiad: ${n}`,
    months: ['styczeń', 'luty', 'marzec', 'kwiecień', 'maj', 'czerwiec', 'lipiec', 'sierpień', 'wrzesień', 'październik', 'listopad', 'grudzień'],
    monTitle: m => `Podsumowanie: ${m}`, monBody: (p, d) => `Zrobione ${p}% zadań${d == null ? '' : d > 0 ? ` (↑ ${d} pkt)` : d < 0 ? ` (↓ ${-d} pkt)` : ' (bez zmian)'}`,
    eTitle: 'Zostało na dziś', eBody: (d, tot, list) => `${tot ? `${d}/${tot} zrobione (${Math.round(d * 100 / tot)}%). ` : ''}Do zrobienia: ${list}`,
  },
  en: {
    pre: (off, tm, k) => k === 0 ? (off ? `In ${fmtOff(off)} · ${tm}` : `Now · ${tm}`) : k === 1 ? `Tomorrow at ${tm}` : `In ${k} days, at ${tm}`,
    fu: tm => `Was due at ${tm} — done?`, done: '✓ Done', missed: '✕ Not done',
    mTitle: 'Good morning ☀️', mBody: (n, list) => `${n} task${n === 1 ? '' : 's'} today: ${list}`,
    yday: n => `Not closed yesterday: ${n}`, dinner: n => `Dinner: ${n}`,
    months: ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'],
    monTitle: m => `${m} summary`, monBody: (p, d) => `${p}% of tasks done${d == null ? '' : d > 0 ? ` (↑ ${d} pts)` : d < 0 ? ` (↓ ${-d} pts)` : ' (no change)'}`,
    eTitle: 'Left for today', eBody: (d, tot, list) => `${tot ? `${d}/${tot} done (${Math.round(d * 100 / tot)}%). ` : ''}Still to do: ${list}`,
  },
};
const short = arr => arr.slice(0, 4).map(t => t.title).join(', ') + (arr.length > 4 ? ` +${arr.length - 4}` : '');

/**
 * Step 1 — what *could* be due right now, from tasks + household settings only (no completions needed).
 * `tasks` = active tasks (endDate >= yesterday) plus one-off tasks not yet closed.
 * Returns [] most of the time, so the runner can stop without further reads.
 */
function candidates({ household: H, tasks, date, minutes }) {
  const out = [];
  for (const t of tasks) {
    if (!t.time) continue;
    for (let k = 0; k <= LOOKAHEAD; k++) {
      const occ = addDays(date, k);
      if (!occursOn(t, occ)) continue;
      const at = k * 1440 + toMin(t.time);
      for (const off of remindOffsets(t)) {
        const fire = at - off;
        if (minutes >= fire && minutes - fire <= WINDOW && minutes <= at + LATE) out.push({ kind: 'pre', key: `${t.id}@${occ}@${off}`, task: t, occ, off, k, late: minutes > at });
      }
    }
    const nag = t.remind?.nag || 0;
    if (nag && t.remind?.on !== false && occursOn(t, date) && minutes - toMin(t.time) >= Math.abs(nag))
      out.push({ kind: 'fu', key: `${t.id}@${date}@fu`, task: t, occ: date, nag });
  }
  if (H.morningAt && minutes >= toMin(H.morningAt) && minutes - toMin(H.morningAt) <= 180) out.push({ kind: 'morning', key: `_morning@${date}` });
  if (H.eveningAt && minutes >= toMin(H.eveningAt)) out.push({ kind: 'evening', key: `_evening@${date}` });
  if (date.endsWith('-01')) {  // month summary on the 1st, at the morning-summary time (09:00 if that is off)
    const at = toMin(H.morningAt || '09:00');
    if (minutes >= at && minutes - at <= 180) out.push({ kind: 'month', key: `_month@${prevMonth(date.slice(0, 7))}` });
  }
  return out;
}

/** Drop candidates already handled (sent = merged notify state of today + yesterday). */
function pending(cands, sent, minutes) {
  return cands.filter(c => {
    const st = sent[c.key];
    if (c.kind !== 'fu') return !st;
    if (!st) return true;
    return c.nag > 0 && st.n < 10 && minutes - st.last >= c.nag;
  });
}

/** Which completion docs step 3 needs (so the runner can fetch exactly those). */
function neededCompletions(cands, date) {
  const ids = new Set(), days = new Set();
  for (const c of cands) {
    if (c.task) ids.add(compId(c.task.id, c.occ));
    if (c.kind === 'morning') { days.add(date); days.add(addDays(date, -1)); }
    if (c.kind === 'evening') days.add(date);
  }
  return { ids: [...ids], days: [...days] };
}

/**
 * Step 3 — build the messages.
 * comps: map compId -> completion (at least the ones neededCompletions asked for)
 * meal: tonight's dinner name or null
 */
function build({ household: H, tasks, cands, sent, comps, meal, date, minutes, monthData }) {
  const M = MSG[H.lang] || MSG.pl, members = H.members || [];
  const to = t => (!t.assignee || t.assignee === 'all') ? members : [t.assignee];
  const actions = [{ action: 'done', title: M.done }, { action: 'missed', title: M.missed }];
  const outbox = [], changed = {};
  for (const c of cands) {
    if (c.task && comps[compId(c.task.id, c.occ)]) { changed[c.key] = c.kind === 'fu' ? { n: 99, last: minutes } : minutes; continue; } // already closed: never check it again
    const t = c.task;
    if (c.kind === 'pre') {
      outbox.push({ uids: to(t), payload: { title: t.title, body: c.late ? M.fu(t.time) : M.pre(c.off, t.time, c.k), tag: `${t.id}_${c.occ}`, data: { task: t.id, date: c.occ }, actions: c.k === 0 ? actions : [] } });
      changed[c.key] = minutes;
    } else if (c.kind === 'fu') {
      outbox.push({ uids: to(t), payload: { title: t.title, body: M.fu(t.time), tag: `${t.id}_${date}`, data: { task: t.id, date }, actions } });
      changed[c.key] = { n: (sent[c.key]?.n || 0) + 1, last: minutes };
    } else if (c.kind === 'month') {
      if (!monthData) continue;
      const ym = c.key.split('@')[1], py = prevMonth(ym), name = M.months[+ym.slice(5) - 1];
      for (const uid of members) {
        const shared = monthData.tasks.filter(t => !t.private);                      // household % never includes private tasks
        const cur = monthStats(shared, monthData.comps, ym).total, prev = monthStats(shared, monthData.comps, py).total;
        const mine = monthStats(monthData.tasks.filter(t => !t.private || t._owner === uid), monthData.comps, ym, { uid }).total;
        if (cur.pct == null) continue;
        const d = prev.pct != null ? cur.pct - prev.pct : null;
        const body = M.monBody(cur.pct, d) + (members.length > 1 && mine.pct != null ? ` · ${H.names?.[uid] || ''} ${mine.pct}%` : '');
        outbox.push({ uids: [uid], payload: { title: M.monTitle(name), body, tag: `month_${ym}`, data: { summary: ym } } });
      }
      changed[c.key] = minutes;
    } else {
      const open = uid => tasks.filter(x => occursOn(x, date) && assignedTo(x, uid) && !comps[compId(x.id, date)])
        .sort((a, b) => (a.time || '99').localeCompare(b.time || '99'));
      for (const uid of members) {
        if (c.kind === 'morning') {
          const o = open(uid), unf = unfinished(tasks, comps, addDays(date, -1), uid).length;
          const parts = [o.length ? M.mBody(o.length, short(o)) : '', unf ? M.yday(unf) : '', meal ? M.dinner(meal) : ''].filter(Boolean);
          if (parts.length) outbox.push({ uids: [uid], payload: { title: M.mTitle, body: parts.join('\n'), tag: `morning_${date}`, data: { date } } });
        } else {
          const all = tasks.filter(x => occursOn(x, date) && assignedTo(x, uid) && comps[compId(x.id, date)]?.status !== 'skip');
          const done = all.filter(x => comps[compId(x.id, date)]?.status === 'done').length;
          const overdue = tasks.filter(x => !isRecurring(x) && x.date < date && x.closed === false && assignedTo(x, uid));
          const o = open(uid).concat(overdue);
          if (o.length) outbox.push({ uids: [uid], payload: { title: M.eTitle, body: M.eBody(done, all.length, short(o)), tag: `evening_${date}`, data: { date } } });
        }
      }
      changed[c.key] = minutes;
    }
  }
  return { outbox, changed };
}

// ===== runner.mjs =====
// Reminder runner that needs nothing but fetch() and WebCrypto, so the SAME code runs
//  - on Cloudflare Workers today (cloudflare-worker.js is this file bundled), and
//  - on a home server later (node server/node-entry.mjs).
// It signs in to Google with the Firebase service account, talks to Firestore over its REST API,
// applies the rules from core.mjs and sends Web Push (VAPID + aes128gcm, RFC 8291/8292).


const te = new TextEncoder();
const b64uEnc = buf => { let s = ''; for (const b of new Uint8Array(buf)) s += String.fromCharCode(b); return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, ''); };
const b64uDec = s => { s = s.replace(/-/g, '+').replace(/_/g, '/'); s += '==='.slice((s.length + 3) % 4); return Uint8Array.from(atob(s), c => c.charCodeAt(0)); };
const concat = (...a) => { const out = new Uint8Array(a.reduce((n, x) => n + x.length, 0)); let o = 0; for (const x of a) { out.set(x, o); o += x.length; } return out; };

/* ---------- Google sign-in with the service account (OAuth JWT bearer) ---------- */
let tokenCache = null;
async function googleToken(sa) {
  if (tokenCache && tokenCache.email === sa.client_email && tokenCache.exp > Date.now() + 120000) return tokenCache.token;
  const now = Math.floor(Date.now() / 1000);
  const head = b64uEnc(te.encode(JSON.stringify({ alg: 'RS256', typ: 'JWT' })));
  const claims = b64uEnc(te.encode(JSON.stringify({ iss: sa.client_email, scope: 'https://www.googleapis.com/auth/datastore', aud: 'https://oauth2.googleapis.com/token', iat: now, exp: now + 3600 })));
  const der = Uint8Array.from(atob(sa.private_key.replace(/-----[^-]+-----/g, '').replace(/\s+/g, '')), c => c.charCodeAt(0));
  const key = await crypto.subtle.importKey('pkcs8', der, { name: 'RSASSA-PKCS1-v1_5', hash: 'SHA-256' }, false, ['sign']);
  const sig = await crypto.subtle.sign('RSASSA-PKCS1-v1_5', key, te.encode(`${head}.${claims}`));
  const r = await fetch('https://oauth2.googleapis.com/token', {
    method: 'POST', headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: `grant_type=urn%3Aietf%3Aparams%3Aoauth%3Agrant-type%3Ajwt-bearer&assertion=${head}.${claims}.${b64uEnc(sig)}`,
  });
  const j = await r.json().catch(() => ({}));
  if (!r.ok || !j.access_token) throw new Error(`Google sign-in failed (${j.error_description || j.error || r.status})`);
  tokenCache = { email: sa.client_email, token: j.access_token, exp: Date.now() + (j.expires_in || 3600) * 1000 };
  return j.access_token;
}

/* ---------- Firestore REST ---------- */
const OPS = { '==': 'EQUAL', '>=': 'GREATER_THAN_OR_EQUAL', '<=': 'LESS_THAN_OR_EQUAL' };
function fromV(v) {
  if ('stringValue' in v) return v.stringValue;
  if ('integerValue' in v) return Number(v.integerValue);
  if ('doubleValue' in v) return v.doubleValue;
  if ('booleanValue' in v) return v.booleanValue;
  if ('nullValue' in v) return null;
  if ('timestampValue' in v) return v.timestampValue;
  if ('mapValue' in v) return fromFields(v.mapValue.fields || {});
  if ('arrayValue' in v) return (v.arrayValue.values || []).map(fromV);
  return null;
}
const fromFields = f => Object.fromEntries(Object.entries(f || {}).map(([k, v]) => [k, fromV(v)]));
function toV(x) {
  if (x === null || x === undefined) return { nullValue: null };
  if (typeof x === 'boolean') return { booleanValue: x };
  if (typeof x === 'number') return Number.isInteger(x) ? { integerValue: String(x) } : { doubleValue: x };
  if (typeof x === 'string') return { stringValue: x };
  if (Array.isArray(x)) return { arrayValue: { values: x.map(toV) } };
  return { mapValue: { fields: toFields(x) } };
}
const toFields = o => Object.fromEntries(Object.entries(o).map(([k, v]) => [k, toV(v)]));
const fieldPath = k => /^[A-Za-z_][A-Za-z_0-9]*$/.test(k) ? k : '`' + k.replace(/\\/g, '\\\\').replace(/`/g, '\\`') + '`';

function firestore(projectId, token, counter) {
  const root = `projects/${projectId}/databases/(default)/documents`;
  const call = async (path, body) => {
    counter.calls++;
    const r = await fetch(`https://firestore.googleapis.com/v1/${path}`, {
      method: body ? 'POST' : 'GET', headers: { authorization: `Bearer ${token}`, 'content-type': 'application/json' },
      body: body ? JSON.stringify(body) : undefined,
    });
    const j = await r.json().catch(() => ({}));
    if (!r.ok) throw new Error(`Firestore ${r.status} ${(Array.isArray(j) ? j[0]?.error?.message : j.error?.message) || ''}`.trim());
    return j;
  };
  const rel = name => name.slice(root.length + 1);
  const doc = d => ({ id: d.name.split('/').pop(), path: rel(d.name), ...fromFields(d.fields) });
  return {
    async list(coll) {
      const out = []; let pt = '';
      do {
        const j = await call(`${root}/${coll}?pageSize=300${pt ? `&pageToken=${encodeURIComponent(pt)}` : ''}`);
        (j.documents || []).forEach(d => out.push(doc(d))); pt = j.nextPageToken || '';
      } while (pt);
      return out;
    },
    async query(parent, coll, filters) {
      const f = filters.map(([field, op, value]) => ({ fieldFilter: { field: { fieldPath: field }, op: OPS[op], value: toV(value) } }));
      const where = f.length === 1 ? f[0] : { compositeFilter: { op: 'AND', filters: f } };
      const j = await call(`${root}/${parent}:runQuery`, { structuredQuery: { from: [{ collectionId: coll }], where } });
      return j.filter(x => x.document).map(x => doc(x.document));
    },
    async getMany(paths) {
      if (!paths.length) return [];
      const j = await call(`${root}:batchGet`, { documents: paths.map(p => `${root}/${p}`) });
      const m = new Map(j.map(x => x.found ? [rel(x.found.name), doc(x.found)] : [rel(x.missing), null]));
      return paths.map(p => m.get(p) ?? null);
    },
    async merge(path, data) {
      await call(`${root}:commit`, { writes: [{ update: { name: `${root}/${path}`, fields: toFields(data) }, updateMask: { fieldPaths: Object.keys(data).map(fieldPath) } }] });
    },
    async remove(path) { await call(`${root}:commit`, { writes: [{ delete: `${root}/${path}` }] }).catch(() => { }); },
  };
}
const plain = d => { if (!d) return d; const { path: _p, ...rest } = d; return rest; };

/* ---------- Web Push (RFC 8291 aes128gcm + RFC 8292 VAPID) ---------- */
async function hkdf(salt, ikm, info, len) {
  const k = await crypto.subtle.importKey('raw', ikm, 'HKDF', false, ['deriveBits']);
  return new Uint8Array(await crypto.subtle.deriveBits({ name: 'HKDF', hash: 'SHA-256', salt, info }, k, len * 8));
}
async function encryptPayload(sub, text, opts = {}) {
  const ua = b64uDec(sub.keys.p256dh), auth = b64uDec(sub.keys.auth);
  const salt = opts.salt || crypto.getRandomValues(new Uint8Array(16));
  const kp = opts.keyPair || await crypto.subtle.generateKey({ name: 'ECDH', namedCurve: 'P-256' }, true, ['deriveBits']);
  const asPub = new Uint8Array(await crypto.subtle.exportKey('raw', kp.publicKey));
  const uaKey = await crypto.subtle.importKey('raw', ua, { name: 'ECDH', namedCurve: 'P-256' }, false, []);
  const ecdh = new Uint8Array(await crypto.subtle.deriveBits({ name: 'ECDH', public: uaKey }, kp.privateKey, 256));
  const ikm = await hkdf(auth, ecdh, concat(te.encode('WebPush: info\0'), ua, asPub), 32);
  const cek = await hkdf(salt, ikm, te.encode('Content-Encoding: aes128gcm\0'), 16);
  const nonce = await hkdf(salt, ikm, te.encode('Content-Encoding: nonce\0'), 12);
  const key = await crypto.subtle.importKey('raw', cek, 'AES-GCM', false, ['encrypt']);
  const ct = new Uint8Array(await crypto.subtle.encrypt({ name: 'AES-GCM', iv: nonce }, key, concat(te.encode(text), new Uint8Array([2]))));
  const head = new Uint8Array(21); head.set(salt, 0); new DataView(head.buffer).setUint32(16, 4096); head[20] = 65;
  return concat(head, asPub, ct);
}
const vapidKeys = new Map();
async function vapidAuth(endpoint, pubB64, privB64, subject) {
  let key = vapidKeys.get(privB64);
  if (!key) {
    const pub = b64uDec(pubB64);
    key = await crypto.subtle.importKey('jwk', { kty: 'EC', crv: 'P-256', d: privB64, x: b64uEnc(pub.slice(1, 33)), y: b64uEnc(pub.slice(33, 65)), ext: true },
      { name: 'ECDSA', namedCurve: 'P-256' }, false, ['sign']);
    vapidKeys.set(privB64, key);
  }
  const h = b64uEnc(te.encode(JSON.stringify({ typ: 'JWT', alg: 'ES256' })));
  const c = b64uEnc(te.encode(JSON.stringify({ aud: new URL(endpoint).origin, exp: Math.floor(Date.now() / 1000) + 12 * 3600, sub: subject || 'mailto:razem@example.com' })));
  const sig = await crypto.subtle.sign({ name: 'ECDSA', hash: 'SHA-256' }, key, te.encode(`${h}.${c}`));
  return `vapid t=${h}.${c}.${b64uEnc(sig)}, k=${pubB64}`;
}
async function sendPush(sub, payload, env) {
  const body = await encryptPayload(sub, JSON.stringify(payload));
  const r = await fetch(sub.endpoint, {
    method: 'POST', body,
    headers: { authorization: await vapidAuth(sub.endpoint, env.VAPID_PUBLIC, env.VAPID_PRIVATE, env.VAPID_SUBJECT),
      'content-encoding': 'aes128gcm', 'content-type': 'application/octet-stream', ttl: '3600', urgency: 'high' },
  });
  return r.status;
}

/* ---------- task list cache: tasks change rarely, so they are re-read only when the app bumps tasksRev ---------- */
const memCache = new Map();

/* ---------- the run ---------- */
async function runOnce(env, { diag = false, log = console.log } = {}) {
  const sa = JSON.parse(env.FIREBASE_SERVICE_ACCOUNT || '{}');
  if (!sa.private_key || !sa.client_email) throw new Error('FIREBASE_SERVICE_ACCOUNT is not the service-account JSON');
  const counter = { calls: 0 };
  const db = firestore(sa.project_id, await googleToken(sa), counter);
  const homes = await db.list('households');
  for (const [i, h] of homes.entries()) {
    await handle(db, h, i + 1, env, { diag, log }).catch(e => log(`home#${i + 1} error: ${e.message}`));
  }
  log(`checked ${homes.length} household(s), ${counter.calls} database calls`);
}

async function handle(db, H, idx, env, { diag, log }) {
  const tag = `home#${idx}`; // never log the household id: it is the invite code
  const hp = `households/${H.id}`, members = H.members || [];
  const { date, minutes } = nowInTz(H.tz || 'Europe/Warsaw');
  const yday = addDays(date, -1);

  // tasks: shared + each member's private ones (users/{uid}/ptasks; the other member can't read those)
  const users = await db.getMany(members.map(u => `users/${u}`));
  const ck = `${H.id}|${date}|${H.tasksRev || 0}|${users.map(u => u?.tasksRev || 0).join(',')}`;
  let tasks = memCache.get(ck);
  if (!tasks) {
    const lists = await Promise.all([
      db.query(hp, 'tasks', [['endDate', '>=', yday]]), db.query(hp, 'tasks', [['closed', '==', false]]),
      ...members.flatMap(u => [db.query(`users/${u}`, 'ptasks', [['endDate', '>=', yday]]), db.query(`users/${u}`, 'ptasks', [['closed', '==', false]])]),
    ]);
    const byId = new Map();
    lists.forEach((l, i) => {
      const owner = i < 2 ? null : members[Math.floor((i - 2) / 2)];
      l.forEach(d => byId.set(d.id, owner ? { ...plain(d), private: true, _owner: owner, assignee: owner } : plain(d)));
    });
    tasks = [...byId.values()];
    memCache.clear(); memCache.set(ck, tasks);
  }
  const ownerOf = new Map(tasks.filter(t => t._owner).map(t => [t.id, t._owner]));
  const compPath = id => { const o = ownerOf.get(id.slice(0, id.lastIndexOf('_'))); return o ? `users/${o}/pcomps/${id}` : `${hp}/completions/${id}`; };

  let cands = candidates({ household: H, tasks, date, minutes });
  log(`${tag} ${date} ${String(Math.floor(minutes / 60)).padStart(2, '0')}:${String(minutes % 60).padStart(2, '0')} tasks=${tasks.length} timed=${tasks.filter(t => t.time).length} due-now=${cands.length}`);
  if (!cands.length && !diag) return;
  const [stT, stY] = await db.getMany([`${hp}/notify/${date}`, `${hp}/notify/${yday}`]);
  const sent = { ...(plain(stY) || {}), ...(plain(stT) || {}) };
  delete sent.id;
  cands = pending(cands, sent, minutes);
  if (diag) log(`${tag} not-yet-sent=${cands.length} members=${members.length}`);
  if (!cands.length) return;

  const need = neededCompletions(cands, date);
  const [byId, subs, meal, ...days] = await Promise.all([
    db.getMany(need.ids.map(compPath)),
    db.list(`${hp}/pushSubs`),
    cands.some(c => c.kind === 'morning') ? db.getMany([`${hp}/meals/${date}`]).then(r => r[0]) : null,
    ...need.days.flatMap(d => [db.query(hp, 'completions', [['date', '==', d]]), ...members.map(u => db.query(`users/${u}`, 'pcomps', [['date', '==', d]]))]),
  ]);
  const comps = {};
  byId.forEach((d, i) => { if (d) comps[need.ids[i]] = plain(d); });
  days.forEach(l => l.forEach(d => { comps[d.id] = plain(d); }));

  let monthData = null;
  const mc = cands.find(c => c.kind === 'month');
  if (mc) {
    const ym = mc.key.split('@')[1], from = monthRange(prevMonth(ym)).first, to = monthRange(ym).last;
    const range = [['date', '>=', from], ['date', '<=', to]];
    const [mt, mcs, ...pv] = await Promise.all([
      db.query(hp, 'tasks', [['endDate', '>=', from]]), db.query(hp, 'completions', range),
      ...members.flatMap(u => [db.query(`users/${u}`, 'ptasks', [['endDate', '>=', from]]), db.query(`users/${u}`, 'pcomps', range)]),
    ]);
    const mtasks = mt.map(plain), mcomps = Object.fromEntries(mcs.map(d => [d.id, plain(d)]));
    members.forEach((u, i) => {
      pv[2 * i].forEach(d => mtasks.push({ ...plain(d), private: true, _owner: u, assignee: u }));
      pv[2 * i + 1].forEach(d => { mcomps[d.id] = plain(d); });
    });
    monthData = { tasks: mtasks, comps: mcomps };
  }

  const { outbox, changed } = build({ household: H, tasks, cands, sent, comps, meal: meal?.name || null, date, minutes, monthData });
  log(`${tag} messages=${outbox.length} phones=${subs.length}`);
  for (const { uids, payload } of outbox) {
    for (const s of subs.filter(s => !s.dead && uids.includes(s.uid))) {
      try {
        const st = await sendPush(s.sub, payload, env);
        if (st === 404 || st === 410) { s.dead = true; await db.remove(s.path); log(`${tag} removed an expired phone`); }
        else log(`${tag} sent to phone ${subs.indexOf(s) + 1} (${st})`);
      } catch (e) { log(`${tag} push failed: ${e.message}`); }
    }
  }
  if (Object.keys(changed).length) {
    await db.merge(`${hp}/notify/${date}`, changed);
    if (changed[`_evening@${date}`]) await db.remove(`${hp}/notify/${addDays(date, -7)}`);
  }
}

/** Sends a test notification to every registered phone (used by the worker's test link). */
async function sendTest(env, { log = console.log } = {}) {
  const sa = JSON.parse(env.FIREBASE_SERVICE_ACCOUNT || '{}');
  const db = firestore(sa.project_id, await googleToken(sa), { calls: 0 });
  for (const [i, h] of (await db.list('households')).entries()) {
    const subs = await db.list(`households/${h.id}/pushSubs`);
    for (const [k, s] of subs.entries()) {
      const st = await sendPush(s.sub, { title: 'Razem', body: 'Test z serwera przypomnień ✓', tag: 'server-test' }, env).catch(e => e.message);
      log(`home#${i + 1} phone ${k + 1}: ${st}`);
    }
  }
}

// ===== worker-entry.mjs =====
// Cloudflare Worker entry. The cron trigger runs the reminder check; the URL only answers with
// ?token=<RUN_TOKEN> (a password you choose): ?token=… runs a check and shows counts, ?token=…&test sends a test push.

export default {
  async scheduled(event, env, ctx) {
    ctx.waitUntil(runOnce(env).catch(e => console.log(`reminder run failed: ${e.message}`)));
  },
  async fetch(request, env) {
    const u = new URL(request.url);
    if (!env.RUN_TOKEN || u.searchParams.get('token') !== env.RUN_TOKEN) return new Response('Razem reminders are running.\n', { status: 200 });
    const lines = [], log = s => lines.push(s);
    try { u.searchParams.has('test') ? await sendTest(env, { log }) : await runOnce(env, { diag: true, log }); }
    catch (e) { lines.push(`error: ${e.message}`); }
    return new Response(lines.join('\n') + '\n', { headers: { 'content-type': 'text/plain; charset=utf-8', 'cache-control': 'no-store' } });
  },
};
